const (
	schemaVersion    = "1.0"
	reportInterval   = 4 * time.Hour
	telemetryURL     = "https://telemetry.flipt.io/v1/track"
	initialTimestamp = "1970-01-01T00:00:00Z"
)

// FliptVersion is set by the server at startup from its build version.
var FliptVersion = "dev"

type state struct {
	Version       string `json:"version"`
	UUID          string `json:"uuid"`
	LastTimestamp string `json:"lastTimestamp"`
}

type event struct {
	Event       string `json:"event"`
	AnonymousID string `json:"anonymousId"`
	Properties  struct {
		UUID    string `json:"uuid"`
		Version string `json:"version"`
		Flipt   struct {
			Version string `json:"version"`
		} `json:"flipt"`
	} `json:"properties"`
}

// Reporter holds the persisted installation identity and sends usage events.
type Reporter struct {
	mu       sync.Mutex
	path     string
	state    state
	version  string
	logger   logrus.FieldLogger
	client   *http.Client
	endpoint string
}

// NewReporter initializes telemetry state. A disabled configuration never touches the filesystem.
func NewReporter(cfg *config.Config, logger logrus.FieldLogger) (*Reporter, error) {
	if cfg == nil || !cfg.Meta.TelemetryEnabled {
		return nil, nil
	}
	dir := cfg.Meta.StateDirectory
	if dir == "" {
		var err error
		dir, err = os.UserConfigDir()
		if err != nil {
			return nil, fmt.Errorf("finding telemetry state directory: %w", err)
		}
		// Use the OS-specific user configuration directory directly.
	}
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, fmt.Errorf("creating telemetry state directory: %w", err)
	}
	path := filepath.Join(dir, "telemetry.json")
	r := &Reporter{path: path, version: FliptVersion, logger: logger, client: &http.Client{Timeout: 10 * time.Second}, endpoint: telemetryURL}
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("reading telemetry state: %w", err)
	}
	if err == nil {
		if err := json.Unmarshal(data, &r.state); err != nil {
			logger.Warnf("reading telemetry state: %v", err)
			r.state = state{}
		}
	}
	if _, err := uuid.FromString(r.state.UUID); err != nil {
		id, err := uuid.NewV4()
		if err != nil {
			return nil, fmt.Errorf("generating telemetry UUID: %w", err)
		}
		r.state.UUID = id.String()
	}
	if _, err := time.Parse(time.RFC3339, r.state.LastTimestamp); err != nil {
		r.state.LastTimestamp = initialTimestamp
	}
	r.state.Version = schemaVersion
	if err := r.writeState(); err != nil {
		return nil, err
	}
	return r, nil
}

func (r *Reporter) writeState() error {
	data, err := json.Marshal(r.state)
	if err != nil {
		t.Fatalf("state directory created: %v", err)
	}
}

func TestReporterStateAndDelivery(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "state")
	cfg := config.Default()
	cfg.Meta.StateDirectory = dir
	FliptVersion = "v1.2.3"
	r, err := NewReporter(cfg, logrus.New())
	if err != nil {
		t.Fatal(err)
	}
	initial := r.state.UUID
	if initial == "" || r.state.Version != schemaVersion {
		t.Fatalf("bad initial state: %+v", r.state)
	}
	if r.state.LastTimestamp != initialTimestamp {
		t.Fatalf("initial timestamp = %q", r.state.LastTimestamp)
	}
	r2, err := NewReporter(cfg, logrus.New())
	if err != nil || r2.state.UUID != initial {
		t.Fatalf("identity changed: %+v, %v", r2, err)
	}
	var got event
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		if err := json.NewDecoder(req.Body).Decode(&got); err != nil {
			t.Error(err)
		}
		w.WriteHeader(http.StatusNoContent)
	}))
	defer server.Close()
	r.endpoint = server.URL
	if err := r.Report(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got.Event != "flipt.ping" || got.AnonymousID != initial || got.Properties.UUID != initial || got.Properties.Version != schemaVersion || got.Properties.Flipt.Version != "v1.2.3" {
		t.Fatalf("wrong event: %+v", got)
	}
	data, err := os.ReadFile(r.path)
	if err != nil {
		t.Fatal(err)
	}
	var persisted state
	if err := json.Unmarshal(data, &persisted); err != nil {
		t.Fatal(err)
	}
	if _, err := time.Parse(time.RFC3339, persisted.LastTimestamp); err != nil {
		t.Fatal(err)
	}
	before := persisted.LastTimestamp
	failure := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { w.WriteHeader(http.StatusInternalServerError) }))
	defer failure.Close()
	r.endpoint = failure.URL
	if err := r.Report(context.Background()); err == nil {
		t.Fatal("expected delivery error")
	}
	data, _ = os.ReadFile(r.path)
	if err := json.Unmarshal(data, &persisted); err != nil {
		t.Fatal(err)
	}
	if persisted.LastTimestamp != before {
		t.Fatalf("timestamp changed after failed report")
	}
}

func TestMalformedStateAndDirectoryFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "telemetry.json")
	if err := os.WriteFile(path, []byte(`{"version":"1.0","uuid":"invalid"}`), 0600); err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.Meta.StateDirectory = dir
	r, err := NewReporter(cfg, logrus.New())
	if err != nil || r.state.UUID == "invalid" {
		t.Fatalf("invalid identity retained: %+v, %v", r, err)
	}
	if r.state.LastTimestamp != initialTimestamp {
		t.Fatalf("repaired timestamp = %q", r.state.LastTimestamp)
	}
	cfg.Meta.StateDirectory = path
	if _, err := NewReporter(cfg, logrus.New()); err == nil {
		t.Fatal("file accepted as state directory")
	}
}

func TestMalformedJSONIsLoggedAndRepaired(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "telemetry.json")
	if err := os.WriteFile(path, []byte(`{invalid`), 0600); err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.Meta.StateDirectory = dir
	logger := logrus.New()
	var logs bytes.Buffer
	logger.SetOutput(&logs)
	r, err := NewReporter(cfg, logger)
	if err != nil {
		t.Fatal(err)
	}
	if r.state.UUID == "" || r.state.LastTimestamp != initialTimestamp {
		t.Fatalf("bad repaired state: %+v", r.state)
	}
	if !bytes.Contains(logs.Bytes(), []byte("reading telemetry state")) {
		t.Fatalf("malformed state was not logged: %q", logs.String())
	}
